UPDATE courses SET
    course_description = '<p>Students will be encouraged to integrate this biological knowledge with their understanding of Aboriginal ways of understanding health and disease in formulating effective strategies required to address health issues.</p> <p> The major is offered in the Bachelor of Science program given its strong health focus. The Aboriginal Health and Wellbeing major, offered from within the Medical School, emphasises an evidence-based approach to decision making, policy development and practice. This emphasis, in combination with a strong grounding in Aboriginal knowledge and understandings, provides a unique opportunity for students undertaking the major to develop an understanding of equity and translation of evidence into policy and practice that reflects the way forward in Closing the Gap in Aboriginal health.</p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>The University of Western Australia welcomes applications from international and domestic school-leavers. If you’re interested in studying one of these majors, find out the admission details below. </p> <!-- RichTextCourseCard.cshtml --> Admission requirements <p> For applicants with recent secondary education, information on admission criteria is available on our <a href="/study/how-to-apply/entry-requirements">entry requirements</a> page or on the <a href="https://handbooks.uwa.edu.au/">UWA Handbook</a> for course specific requirements and prerequisites.<br/> </p> Admission requirements <!-- RichTextCourseCard.cshtml --> Maths prerequisite <p><strong>Prerequisite subjects:</strong> Mathematics Applications ATAR or a Mathematics unit may be required as part of your degree.</p> Maths prerequisite <!-- RichTextCourseCard.cshtml --> ADMISSION REQUIREMENT English competency <p>English is the language of instruction and assessment at UWA and you will need to meet the <a href="https://www.uwa.edu.au/study/how-to-apply/english-language-requirements">English language requirements</a> of the University to be eligible for a place.</p> <p>Minimum overall IELTS score of 6.5, with no band less than 6.0.</p> ADMISSION REQUIREMENT English competency',
    apply_form = 'https://www.uwa.edu.au/study/courses/aboriginal-health-and-wellbeing',
    updated_at = NOW()
WHERE cricos_course_code = '075827C';
