UPDATE courses SET
    course_description = '<p>Agribusiness encompasses the entire food production process from business activities involved in production, financing, processing and marketing of food and fibre in order to feed a growing population. With the need to feed the world, the agribusiness sector is emerging to be one of the most important and dynamic in terms of production, consumer spending and employment. Undertaking the Agribusiness major will provide you with the opportunity to be part of this growing sector.</p> <p>The major will prepare you to apply business and economic principles to address global challenges in food security, farming systems and evolving consumer markets. You''ll also learn about the management of businesses operating from the farm gate to consumer plates.</p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>The University of Western Australia welcomes applications from international and domestic school-leavers. If you’re interested in studying one of these majors, find out the admission details below. </p> <!-- RichTextCourseCard.cshtml --> Admission requirements <p> For applicants with recent secondary education, information on admission criteria is available on our <a href="/study/how-to-apply/entry-requirements">entry requirements</a> page or on the <a href="https://handbooks.uwa.edu.au/">UWA Handbook</a> for course specific requirements and prerequisites.<br/> </p> Admission requirements <!-- RichTextCourseCard.cshtml --> Mathematics requirement <p>This major requires a certain level of Mathematics. If you do not meet this level, you may be able to take additional Mathematics units in your first year to satisfy this requirement. </p> <p>WACE prerequisite: Mathematics Methods ATAR</p> Mathematics requirement <!-- RichTextCourseCard.cshtml --> ADMISSION REQUIREMENT English competency <p>English is the language of instruction and assessment at UWA and you will need to meet the <a href="https://www.uwa.edu.au/study/how-to-apply/english-language-requirements">English language requirements</a> of the University to be eligible for a place.</p> <p>Minimum overall IELTS score of 6.5, with no band less than 6.0.</p> ADMISSION REQUIREMENT English competency',
    apply_form = 'https://www.uwa.edu.au/study/courses/agribusiness',
    updated_at = NOW()
