UPDATE courses SET
    course_description = '<p>Creating sustainable and vibrant communities and economies are key challenges facing our world, particularly in the context of rising inequality and significant global environmental change. As a discipline, Human Geography - the study of how historical, economic, political, demographic, social and environmental processes intersect to shape life in different places – is uniquely positioned to address these major challenges. </p> <p> In this course, you will gain a comprehensive understanding of the complex, interwoven processes shaping human activity in cities and regions at a range of spatial scales from the global to the local. You’ll also develop critical, technical, and communicative skills to address major human and environmental policy challenges. Analysis of processes of multi-scalar urbanisation, economic transition in regional areas, population change, and adaptation to climate change will be supported by extensive experience in data collection, analysis and interpretation, including the use of Geographic Information Systems and remotely sensed data. The unique focus on intersecting processes within Human Geography as a discipline, along with a focus on applied, field-based learning, technical and critical skill development (for example in spatial data analysis), and addressing real-world policy problems provides a diverse range of career opportunities for course graduates. </p> <p> Career pathways include (but are not limited to): policy roles within government agencies and departments that oversee community development, regional development and planning, local governance, and resources; in private firms and consultancies that specialize in spatial, social, economic and demographic data analytics; and in the not-for-profit community, aid and development sectors nationally and globally. </p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>The University of Western Australia welcomes applications from international and domestic school-leavers. If you’re interested in studying one of these majors, find out the admission details below. </p> <!-- RichTextCourseCard.cshtml --> Admission requirements <p> For applicants with recent secondary education, information on admission criteria is available on our <a href="/study/how-to-apply/entry-requirements">entry requirements</a> page or on the <a href="https://handbooks.uwa.edu.au/">UWA Handbook</a> for course specific requirements and prerequisites.<br/> </p> Admission requirements <!-- RichTextCourseCard.cshtml --> ADMISSION REQUIREMENT English competency <p>English is the language of instruction and assessment at UWA and you will need to meet the <a href="https://www.uwa.edu.au/study/how-to-apply/english-language-requirements">English language requirements</a> of the University to be eligible for a place.</p> <p>Minimum overall IELTS score of 6.5, with no band less than 6.0.</p> ADMISSION REQUIREMENT English competency',
    apply_form = 'https://www.uwa.edu.au/study/courses/applied-human-geography',
    updated_at = NOW()
WHERE cricos_course_code = '058936F';
