UPDATE courses SET
    course_description = '<p> The Architecture extended major prepares you for postgraduate studies by introducing a range of technologies and production methods that encourage you to imagine a variety of design outcomes and their applications. You''ll be introduced to different technologies and production methods to create drawings, models and prototypes. You''ll also make investigations into design communication, sustainable design and relevant historical, theoretical and ethical aspects of architecture. At the end of your degree you''ll be able to use your facility for creative and rational inquiry to analyse and provide solutions to design problems. </p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
