UPDATE courses SET
    course_description = '<p>By completing this Combined Bachelor''s and Master''s course you will graduate with both a <a href="/study/courses/bachelor-of-biological-science">Bachelor of Biological Science</a> and a <a href="/study/courses/master-of-biological-science">Master of Biological Science</a>.</p> <p>In your first three years, you will complete your selected major in the <a href="/study/courses/wildlife-conservation-extended-major">Wildlife Conservation Extended Major</a> or <a href="/study/courses/biodiversity-and-evolution">Biodiversity and Evolution Extended Major</a>, followed by a semester of postgraduate study. Gain an appreciation of how living organisms, ranging from microbes to megaflora and megafauna, grow, reproduce, adapt and evolve. You will learn how species and ecological communities can be managed, conserved and restored, using techniques ranging from genetic analysis to data collection from whole populations and ecosystems, to big data synthesis science.</p> <p>You will then complete a final year of postgraduate study in the <a href="/study/courses/master-of-biological-science">Master of Biological Science</a> which will provide you with the ability to extend your biological and analytical knowledge and skills obtained from the undergraduate program and the opportunity to develop independent thinking. You will have the opportunity to explore and focus on areas of interest and specialise in Conservation Biology, Ecology or Zoology.</p> <em>If you decide not to continue in the CBM you can exit after three years with a Bachelor of Biological Science (Advanced). Note that the Advanced Bachelor Degree is available only as a CBM exit award. It is not offered for direct enrolment and is not awarded on completion of the CBM.</em>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
