UPDATE courses SET
    course_description = '<p>By completing this combined bachelor''s and master''s course you will graduate with both a <a href="/study/courses/bachelor-of-earth-sciences">Bachelor of Earth Sciences</a> and a <a href="/study/courses/master-of-geoscience">Master of Geoscience</a>. </p> <p>In your first three years you will complete the <a href="/study/courses/integrated-earth-and-marine-sciences-extended-major">Integrated Earth and Marine Sciences Extended Major</a> which focuses on key knowledge and practical skills in the collection and interpretation of scientific data in both terrestrial and marine settings as well as data analysis and synthesis techniques, followed by a semester of postgraduate study.</p> <p>You will then complete a final year of postgraduate study in the <a href="/study/courses/master-of-geoscience">Master of Geoscience</a> which includes core units that seek to ensure you have strong interdisciplinary and disciplinary knowledge and technical skills in geoscience to take advantage of diverse career opportunities in industry, government, consultancies and research institutions. Elective units provide additional breadth and a research project or capstone units provide specific advanced disciplinary knowledge and skills.</p> <br/> <em>If you decide not to continue in the CBM you can exit after three years with a Bachelor of Earth Sciences (Advanced). Note that the Advanced Bachelor Degree is available only as a CBM exit award. It is not offered for direct enrolment and is not awarded on completion of the CBM. </em>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
