UPDATE courses SET
    course_description = '<p>This degree is designed to build your foundation in business and hospitality management, combining core areas such as leadership, marketing, economics and global business practices with specialised hospitality studies. This integrated approach ensures you develop both the theoretical understanding and practical capability required in a service-driven industry.</p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<!-- RichTextCourseCard.cshtml --> Admission Requirements <p>To be considered for admission to this course an applicant must have— </p> <ul> <li>achieved an ATAR of at least 70; <strong>or</strong> </li> <li>achieved a score of at least 100 in <a href="/study/how-to-apply/admission-entry-pathways/experience-based-entry">UWA''s Experienced-based Entry</a> assessment; <strong>or</strong></li> <li>a place in a relevant UWA access program; <strong>and</strong></li> <li>demonstrate <a></a><a href="https://www.uwa.edu.au/study/how-to-apply/english-language-requirements">English language competence</a>; <strong>and</strong></li> <li><a href="https://www.uwa.edu.au/study/how-to-apply/english-language-requirements"></a>satisfy any prerequisites for your preferred majors (refer to individual major descriptions for prerequisite details)</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> Admission entry to UWA <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p> Admission Requirements',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-hospitality-management',
    updated_at = NOW()
WHERE cricos_course_code = '120707M';
