UPDATE courses SET
    course_description = '<p><p>The Bachelor of Media and Communication offers applied learning opportunities and skills for those interested in working directly in media and communication industries.</p> <p>Focused on core techniques of ideation, engagement, and impact, the degree is structured to develop your creativity, incorporating various industry facing activities.</p> <p>This interdisciplinary program offers a unique learning environment designed to span various professional areas, including media production, journalism, strategic communication, and digital storytelling. This equips you with the versatile skills in media development and analysis, ensuring you graduate ready to navigate the dynamic digital culture, where responsible and high-level communication will be key to success.</p></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<!-- RichTextCourseCard.cshtml --> Admission Requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 70</li> <li>demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a> - applicants presenting with IELTS Academic require an overall score of at least 6.5 and no band less than 6.0</li> <li> satisfy any prerequisites for your preferred majors (refer to individual major descriptions for prerequisite details)</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> <p>Assured Pathway information</p> <p> If you have a professional career in mind, take advantage of one of our <a href="https://www.uwa.edu.au/study/courses-and-careers/our-courses-explained#postgrad">Assured Pathways</a>. An Assured Pathway gives you an assured place in one of our postgraduate professional courses (such as Law, Engineering or Medicine) from the start of your studies with us. The pathways combine a range of undergraduate and postgraduate courses, providing you with a clearer direction to your career of choice.</p> <p>Admission entry to UWA </p> <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p> Admission Requirements',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-media-and-communication',
    updated_at = NOW()
