-- ⚠️ Skipped (duplicate CRICOS): https://www.uwa.edu.au/study/courses/bachelor-of-molecular-sciences-and-master-of-biomedical-science
UPDATE courses SET
    course_description = '<p>By completing this Combined Bachelor''s and Master''s course you will graduate with both a <a href="/study/courses/bachelor-of-molecular-sciences">Bachelor of Molecular Sciences</a> and a <a href="/study/courses/master-of-biotechnology">Master of Biotechnology</a>.</p> <p>In your first three years, you will complete your selected extended major in <a href="/study/courses/molecular-life-sciences-extended-major">Molecular Life Sciences</a>. You will develop an understanding of biological function at the molecular level and how this knowledge integrates into an understanding of how individual cells and entire organisms function. Emphasis is placed on developing and practicing the laboratory skills and technologies of cutting-edge molecular life sciences. Both theoretical and practical information is presented in the contexts of health sciences and agriculture. During this time you will also undertake a semester of postgraduate study.</p> <p>You will then complete a final year of postgraduate study in the Master of Biotechnology where you have the option to specialise in Biochemistry and Molecular Biology, Genetics and Genomics, Synthetic Biology, Environmental and Agricultural Biotechnology or AQUAtech, in combination with skills in entrepreneurship and commercialisation.</p> <br/> <em>If you decide not to continue in the CBM you can exit after three years with a Bachelor of Molecular Sciences (Advanced). Note that the Advanced Bachelor Degree is available only as a CBM exit award. It is not offered for direct enrolment and is not awarded on completion of the CBM. </em>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
