UPDATE courses SET
    course_description = '<p><p>Our Bachelor of Nursing (Honours) is Australia''s first four-year integrated Honours degree, giving you a head start in your nursing career. With immersive simulation learning, unique real-world experiences and personalised mentorship, you''ll graduate confident, capable and ready to make a real impact from day one.</p> <p>Designed with industry partners, it offers flexible delivery across Western Australia and beyond. A final year internship will prepare graduates to excel in a range of health care settings, meeting the diverse healthcare needs of individuals and communities.</p> <strong>Entry pathways</strong> <p>- Completed a Certificate in a health-related area</p> <p>- Indigenous entry pathways, visit our <a href="https://www.uwa.edu.au/study/support-information/indigenous-students">study Indigenous page</a></p> <p>- University enabling programs, visit out <a href="https://www.uwa.edu.au/study/how-to-apply/pathways-and-eligibility/programs/enabling-programs">enabling programs page</a></p> <p>- Start your application today through <a href="https://www.uwa.edu.au/study/how-to-apply?gclsrc=aw.ds&amp;gad_source=1&amp;gad_campaignid=21315233965&amp;gbraid=0AAAAA9uRkSXSx_dIZES11wbPY0pw0MMfY&amp;gclid=Cj0KCQiAyP3KBhD9ARIsAAJLnna-J7rL-rDnAQO1gjaESU2oU0FVfsEReAQ0a_4tM3JchVcWayYPw2IaApEDEALw_wcB">UWA Apply</a></p></p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<h5>Inherent requirements</h5> <p>To ensure safety of the public and support your decision making about your suitability for the course, a series of inherent requirements are detailed in the <a href="/study/-/media/uwafs/hms/docs/department-of-nursing-inherent-requirements-policy.pdf">Department of Nursing Inherent Requirements Policy</a> . The inherent requirement statements specify the requirements for student admission and progression in the Bachelor of Nursing (Honours). These inherent requirements should be read in conjunction with other course information and Nursing and Midwifery Board of Australia (NMBA) publications such as <a href="https://www.ahpra.gov.au/Notifications/mandatorynotifications.aspx">Guidelines for Mandatory Notifications</a>, <a href="/study/-/media/project/uwa/uwa/seek-wisdom/nursing-and-midwifery-board---codes-and-guidelines---professional-boundaries-for-nurses.pdf">A Nurse’s Guide to Professional Boundaries</a> and <a href="https://www.nursingmidwiferyboard.gov.au/Codes-Guidelines-Statements/Professional-standards/registered-nurse-standards-for-practice.aspx">Registered Nurse Standards for Practice</a>. </p> <p>You will be required to acknowledge that you meet these inherent requirements as part of the application process, and then each time you enrol in a professional practice unit. If you experience challenges in meeting these requirements because of a disability, chronic health condition or any other reason, you should discuss your concerns with the <a href="/cdn-cgi/l/email-protection#bedcccd7da90ced6d7d2d2d7cecdfecbc9df90dbdacb90dfcb81cdcbdcd4dbddca83f7d0d6dbccdbd0ca9eccdbcfcbd7ccdbd3dbd0cacd9e939efcdfddd6dbd2d1cc9ed1d89ef0cbcccdd7d0d99e96f6d1d0d1cbcccd97">Course Director</a> in the first instance. The university can assist you with a plan for reasonable adjustments to support you to meet the inherent requirements where possible, in consultation with the Course Director. </p> <p><strong>Entry pathways</strong></p> <p>Successful completion of an AQF Certificate IV in the following:</p> <ul> <li>52895WA Certificate IV in Preparation for Health and Nursing Studies</li> </ul> <ul> <li>HLT41120 Certificate IV in Health Care </li> </ul> <ul> <li>CHC43015 Certificate IV in Ageing Support </li> </ul> <ul> <li>HLT43021 Certificate IV in Allied Health Assistance </li> </ul> <ul> <li>CHC43315 Certificate IV in Mental Health </li> </ul> <ul> <li>CHC43415 Certificate IV in Leisure and Health </li> </ul> <ul> <li>CHC43215 Certificate IV in Alcohol and Other Drugs </li> </ul> <ul> <li>CHC43121 Certificate IV in Disability </li> </ul> <ul> <li>CHC40421 Certificate IV in Youth Work </li> </ul> <ul> <li>HLT40213 Certificate IV in Aboriginal and/or Torres Strait Islander Primary Health Care Practice </li> </ul> <ul> <li>HLT46015 Certificate IV in Population Health </li> </ul> <ul> <li>HLT46115 Certificate IV in Indigenous Environmental Health</li> </ul> <p><strong>OR</strong></p> <p>ATAR of 70 (adjustments may apply to rural/remote students)</p> <p><strong>OR</strong></p> <p>Indigenous entry pathways, visit our <a href="https://www.uwa.edu.au/study/support-information/indigenous-students">study Indigenous page</a></p> <p><em>Start your application today through <a href="https://www.uwa.edu.au/study/how-to-apply?gclsrc=aw.ds&amp;gad_source=1&amp;gad_campaignid=21315233965&amp;gbraid=0AAAAA9uRkSXSx_dIZES11wbPY0pw0MMfY&amp;gclid=Cj0KCQiAyP3KBhD9ARIsAAJLnna-J7rL-rDnAQO1gjaESU2oU0FVfsEReAQ0a_4tM3JchVcWayYPw2IaApEDEALw_wcB">UWA Apply</a></em></p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-nursing-honours',
    updated_at = NOW()
WHERE cricos_course_code = '119495F';
