UPDATE courses SET
    course_description = '<p>The Graduate Diploma in International Relations is a professionally oriented postgraduate course studied over two semesters (full-time equivalent). It offers you the opportunity to gain expertise in international relations, with a particular focus on our dynamic Indo-Pacific and Indian Ocean regions. <br/> <br/> The course provides you with knowledge, skills and networks to prepare you for a rewarding career in foreign affairs and diplomacy, government, international and non-governmental organisations, the media and education. The program is structured by a core component, where you will gain knowledge of the major sub-fields including International Relations Theory and Practice, International Security, International Political Economy, the Evolution of International Society, and Governance in the International System. Elective units include a focus on important cross-cutting themes such as human rights, democracy, religion and non-governmental organisations, as well as on key global regions and powers. <br/> <br/> The course offers a credited internship unit which can be undertaken with local, national and international organisations, such as government departments, embassies, think tanks, NGOs or regional institutions. High achieving students can undertake research design training. Students can also engage directly with our UWA and affiliated research and policy centres, including the Public Policy Institute, the Centre for Muslim States and Societies, the Africa Research &amp; Engagement Centre, the Korea Research Centre, the Australia India Institute, the Australia Indonesia Institute, the Perth USAsia Centre and the Australian Institute of International Affairs, as well as our international networks including the Worldwide Universities Network.</p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Ready for the next step?</p> <p>Find out how to apply through our simple online application process. </p> <p>We''ll guide you through our entry requirements, admission pathways available to you and application deadlines for your chosen course. </p> <p>We can’t wait for you to join us! </p> <p><a href="/study/how-to-apply">Apply now</a></p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/graduate-diploma-in-international-relations',
    updated_at = NOW()
