UPDATE courses SET
    course_description = '<p>Its scope spans millennia, its object of study is humanity, its sources are everywhere and everything. History’s endeavour is unashamedly vast, daunting and challenging. Studying history means learning how to learn about the past, it means engaging with its wonders and horrors, and it means joining in its telling and retelling. </p> <p>Uncover the deep causes of events such as the American Revolution or the First World War, and discover how women and men experienced the medieval world or the colonisation of Australia. History introduces you to the complexities involved in these pursuits and requires you to use both imagination and reason. Studying history will immerse you in discovery, debate, discussion, understanding, surprise and awe, and it will require of you rigour, reason, questioning, imagination and passion. By studying history, you will be part of the process by which humanity’s memory itself comes to be made.</p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>The University of Western Australia welcomes applications from international and domestic school-leavers. If you’re interested in studying one of these majors, find out the admission details below. </p> <!-- RichTextCourseCard.cshtml --> Admission requirements <p> For applicants with recent secondary education, information on admission criteria is available on our <a href="/study/how-to-apply/entry-requirements">entry requirements</a> page or on the <a href="https://handbooks.uwa.edu.au/">UWA Handbook</a> for course specific requirements and prerequisites.<br/> </p> Admission requirements <!-- RichTextCourseCard.cshtml --> ADMISSION REQUIREMENT English competency <p>English is the language of instruction and assessment at UWA and you will need to meet the <a href="https://www.uwa.edu.au/study/how-to-apply/english-language-requirements">English language requirements</a> of the University to be eligible for a place.</p> <p>Minimum overall IELTS score of 6.5, with no band less than 6.0.</p> ADMISSION REQUIREMENT English competency',
    apply_form = 'https://www.uwa.edu.au/study/courses/history',
    updated_at = NOW()
WHERE cricos_course_code = '116871M';
