UPDATE courses SET
    course_description = '<p>This course aims to improve the knowledge, understanding and practical skills of practitioners currently, or prospectively working in the human performance industry.</p> <p>Currently, vocationally-focussed courses relating to human high-performance are dedicated specifically to professional sport however, peak performance is also critical for productivity, safety and effectiveness in other domains (e.g. occupational health and safety, mining, defence, performing arts etc.). This course will expand on the knowledge and practices in high performance sport, and make it relevant to industry. </p> <p>You''ll be exposed to advanced level units that build upon knowledge gained in your undergraduate studies, especially in regards to applying scientific principles and techniques to improve human performance using the latest sport science knowledge.</p> <p>The lectures, laboratories and practical sessions embedded within the core units are informed by contemporary research, providing an evidence basis for human performance interventions. As such, you will not only develop practical skills, but also critical thinking and research skills to enable them to be active participants in the high performance and sport science industry.</p>',
    course_duration_per_week = 78,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
