UPDATE courses SET
    course_description = '<p> Advance your knowledge in international law and open up career opportunities in government, non-government organisations, inter-governmental organisations, and private institutions where international law is relevant. <br/> <br/> Taught by a diverse team of international law experts with extensive backgrounds in practice and research in international law, our award-winning teaching staff bring a practical, real-world perspective to international law. This course is suited to both the current law practitioner and those pursuing a career in Australia or overseas relevant to international law in government, non-governmental organisations, inter-governmental organisations and private institutions where international law is relevant. <br/> <br/> The course is available to both law and non-law graduates, and is particularly complementary to other disciplines such as international relations, economics and history. Study begins with core units in the foundations of international law, theory, method and contemporary issues, as well as foundations of public international law. You can then specialise by electing units from areas such as international criminal, human rights, environmental, oil and gas, and World Trade Organization law. You can also undertake a major research paper to further deepen your knowledge and critique of a specific field of international law. You will apply the law to real-world situations and learn the skills needed to implement international law knowledge into the workplace, including research skills, oration and critical analysis. </p>',
    course_duration_per_week = 52,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Ready for the next step?</p> <p>Find out how to apply through our simple online application process. </p> <p>We''ll guide you through our entry requirements, admission pathways available to you and application deadlines for your chosen course. </p> <p>We can’t wait for you to join us! </p> <p><a href="/study/how-to-apply">Apply now</a></p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/master-of-international-law',
    updated_at = NOW()
WHERE cricos_course_code = '083868E';
