UPDATE courses SET
    course_description = '<p>In the AUDRC Master of Urban Design, you''ll develop an in-depth understanding of urban design theories and issues; techniques of urban analysis; and skills for the design and development of cities and urban places. The course consists of a first year of focused studies in history, theory, implementation strategy and studio-based learning; and a second year of independent supervised study (research dissertation) OR a coursework focus area in Landscape Design or Geographic Information Systems (GIS). </p> <p>The Master of Urban Design (by dissertation) builds upon the Graduate Certificate and the Graduate Diploma by allowing you to devote the final two semesters to an exegesis and/or major design project, enabling you to accrue significant intellectual and creative experience commensurate with beginning a career as an urban designer. </p> <p>Upon graduating with a Master of Urban Design, you''ll be qualified to participate in all levels of the urban design profession and in particular to function as the lead consultant responsible for the production and critical evaluation of urban design proposals. The demand for this program is in private planning, architectural and landscape design consultancies; local and state government planning and development departments. </p> <p>Entry into this course requires an undergraduate degree with a weighted average of at least 50%. Students from all fields are accepted. Australian and International students are welcome to apply, and the course is delivered both on-campus and online. Students who have completed related postgraduate courses can receive advanced standing so that the Master of Urban Design can be undertaken in between 1 and 2 years, depending on prior learning.</p>',
    course_duration_per_week = 104,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<p>Ready for the next step?</p> <p>Find out how to apply through our simple online application process. </p> <p>We''ll guide you through our entry requirements, admission pathways available to you and application deadlines for your chosen course. </p> <p>We can’t wait for you to join us! </p> <p><a href="/study/how-to-apply">Apply now</a></p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/master-of-urban-design',
    updated_at = NOW()
WHERE cricos_course_code = '074757J';
