UPDATE courses SET
    course_description = '<p>Mathematics provides a comprehensive and in-depth study of the principles, theories, and applications of mathematics. You''ll develop strong analytical and problem-solving skills, enhance your reasoning abilities, and build a solid foundation in various branches of mathematics.</p> <p>Essential areas covered include calculus, linear algebra, abstract algebra, probability and statistics, differential equations, mathematical modelling, and more.</p> <p>The single major in Mathematics allows you to undertake a second major in another discipline, for example statistics, physics, computer science, data science, business, or engineering. This interdisciplinary approach enables you to broaden your knowledge and skills, complementing your mathematical expertise with insights from another field. Tailor your studies further by choosing elective units that align with your interests and career goals.</p>',
    course_duration_per_week = NULL,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
