UPDATE courses SET
    course_description = '<p><p>From mobile data and cloud computing to artificial intelligence and advanced software development, UWA’s Advanced Bachelor of Computer Science (Honours) gives you the tools and techniques to embrace technological challenges and devise innovative solutions to transform the way we live.</p> <p>Whether you choose to specialise in Artificial Intelligence, International Cybersecurity Computing and Data Science or Quantum Computing, you’ll gain the relevant, practical skills, knowledge and connections to forge an exciting career developing new technologies and advanced programming to overcome challenges in business, science and society.</p> <br/></p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = 'Admission requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 90</li> <li>demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a></li> <li>completed prerequisite: Mathematics Methods ATAR</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> Admission entry to UWA <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p>',
