UPDATE courses SET
    course_description = '<p><p>The Bachelor of Agribusiness prepares you for employment in areas related to agriculture, including finance, marketing, policy formation, business management and rural development. Learn the business and economics skills needed to assume managerial and leadership roles. As part of the degree, take 12 core units with the opportunity to take electives to pursue your interests.</p></p>',
