    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = 'Admission Requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>Achieve the University’s minimum entry score</li> <li>Demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a></li> <li>Satisfy any prerequisites for your preferred majors (refer to individual major descriptions for prerequisite details)</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> Assured Pathway information If you have a professional career in mind, take advantage of one of our <a href="https://www.uwa.edu.au/study/courses-and-careers/our-courses-explained#postgrad">Assured Pathways</a>. An Assured Pathway gives you an assured place in one of our postgraduate professional courses (such as Law, Engineering or Medicine) from the start of your studies with us. The pathways combine a range of undergraduate and postgraduate courses, providing you with a clearer direction to your career of choice.<br/> Admission entry to UWA <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-agribusiness',
    updated_at = NOW()
WHERE cricos_course_code = '107572H';
