UPDATE courses SET
    course_description = '<p>A Bachelor of Biological Science from UWA will equip you with skills and knowledge that are highly valued and sought after by a diverse range of employers around the globe, and enable you to understand the vulnerabilities and resilience of life on our planet. You’ll explore the growth, reproduction, adaptation and evolution of living organisms and discover how species and ecological communities can be managed, conserved and restored.</p>',
