UPDATE courses SET
    course_description = '<p><p>The Engineering program at UWA has been developed with industry to equip you with the skills to succeed in your future careers. The course is built upon three core principles: Relevance, Integration and Excellence. Engineering at UWA is relevant to the contemporary world of engineering, integrates knowledge, technical capability and practical skills to create exceptional graduates.</p> <p>In this course, you’ll complement your course content with work integrated learning (450-hour practical), co-curricular activities (including engineering clubs such as UWA Young Engineers, UWA Motorsport and specialisation specific clubs) and professional skills development to become part of the community of UWA engineering graduates preferred by industry for your technical skills, professional integrity and ability to solve complex open-ended problems.</p> <p>In four years, you’ll graduate as an industry-ready engineer specialising in your choice of Automation and Robotics, Biomedical, Chemical, Civil, Electrical and Electronic, Environmental, Mechanical, Mining or Software engineering.</p></p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = 'Admission requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 80</li> <li>demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a></li> <li>obtain a scaled score of at least 50 in prerequisite: Mathematics Methods ATAR</li> <li>obtain a scaled score of at least 50 in one of the following three subjects*: Chemistry ATAR, Physics ATAR or Mathematics Specialist ATAR</li> </ul> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> <p><em>*All three ATAR subjects are recommended. If you do not have all three, then you can use up to two of your free electives to pick up missing prerequisite knowledge in your first year. </em></p> Admission entry to UWA <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p> <p>If you don’t meet these entry requirements, you can apply for admission to the Bachelor of Science and subsequently apply to transfer into this course, subject to meeting course transfer requirements set out in the course rules.</p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-engineering-honours',
    updated_at = NOW()
WHERE cricos_course_code = '106081B';
