UPDATE courses SET
    course_description = '<p>Doctor of Musical Arts (in composition) students are required to prepare under supervision and present for examination—a portfolio of original compositions in a variety of genres, deemed to be of sufficient scale and duration, which show the highest level of technical accomplishment and imaginative resource; a 45-minute lecture/demonstration followed by a 15-minute discussion on a topic related to the student''s research or compositions; and a thesis (30,000 to 40,000 words) on a topic related to one or more aspects of the composition portfolio.<br/> <br/> Doctor of Musical Arts (in performance) students are required to prepare under supervision and present for examination—two recitals of normally 70 to 90 minutes'' duration which demonstrate professional executant skill and interpretative ability; a 45-minute lecture/demonstration followed by a 15-minute discussion session on a topic related to the student''s research; and a thesis (30,000 to 40,000 words) on a topic related to one or more aspects of the performances.</p>',
