UPDATE courses SET
    course_description = '<p>This course equips you with the knowledge, skills, and experience to graduate ready to begin your teaching career. Develop your knowledge and understanding of how children learn and the implications for teaching and how to create safe, inclusive, engaging and supportive learning environments, combined with hands-on learning as you spend over 100 days of professional placement in primary schools, starting from your first semester.</p>',
    course_duration_per_week = 208,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<!-- RichTextCourseCard.cshtml --> Admission Requirements <p>To be considered for admission to this course an applicant must have— </p> <p>(a) achieved an ATAR of at least 70, or equivalent as recognised by UWA; <strong>or</strong> </p> <p>(b) an assured pathway offer; <strong>or</strong></p> <p>(c) achieved a score of at least 100 in <a href="/study/how-to-apply/admission-entry-pathways/experience-based-entry">UWA''s Experienced-based Entry</a> assessment; <strong>or</strong></p> <p>(d) a place in a relevant UWA access program</p> Admission Requirements <!-- RichTextCourseCard.cshtml --> ADMISSION REQUIREMENT English competency <p>English is the language of instruction and assessment at UWA and you will need to meet the <a href="/study/how-to-apply/english-language-requirements">English language requirements</a> of the University to be eligible for a place.</p> <p>This course has higher ELC requirements. Applicants presenting with the IELTS Academic require an overall score of at least 7.5, a minimum 7.0 in the reading and writing bands, and a minimum score of 8.0 in the listening and speaking bands. For more information visit <a href="https://www.uwa.edu.au/study/How-to-apply/english-language-requirements/postgrad-research-english-language-requirements">ELC requirements</a>.</p> ADMISSION REQUIREMENT English competency <!-- RichTextCourseCard.cshtml --> ADMISSION REQUIREMENT A guide to writing your Personal Statement <p>As part of your application for this course, you’ll be asked to submit a Personal Statement. To support you in taking that first step with confidence, we’ve created a <a href="/study/-/media/documents/schools/graduate-school-of-education/personal-statement-guide_web2.pdf">Personal Statement Guide</a>.</p> <p>This guide explains what a Personal Statement is, why it’s an important part of your application, and is a useful resource to get you started.</p> <p>Once you are ready, use this form to <a href="https://forms.office.com/r/AajgzQyMQR">submit your Personal Statement online</a> for assessment as part of your application.</p> ADMISSION REQUIREMENT A guide to writing your Personal Statement',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-education-primary-honours',
    updated_at = NOW()
WHERE cricos_course_code = '114337E';
UPDATE courses SET
    course_description = '<p><p>Challenge yourself with the Bachelor of Geographical and Spatial Science where you''ll develop fundamental spatial science skills, knowledge and techniques to solve the world''s biggest environmental issues.</p> <p>This course has a strong focus on understanding the environmental processes including climate and hydrology that interact with landscapes, people and drive economies, including broader geography principles, demography and regional development. </p></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = 'Admission requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve an ATAR of 80</li> <li>demonstrate <a href="/study/how-to-apply/english-language-requirements">English language competence</a></li> <li>completed prerequisites: Mathematics Methods ATAR or Mathematics Applications ATAR with a mathematics units taken in your first year of study. Students without ATAR mathematics will take two first year mathematics units. </li> </ul> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> Admission entry to UWA <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p> <p>If you don’t meet these entry requirements, you can apply for admission to the Bachelor of Science and subsequently apply to transfer into this course, subject to meeting course transfer requirements set out in the course rules.</p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-geographical-and-spatial-science',
    updated_at = NOW()
WHERE cricos_course_code = '114375K';
UPDATE courses SET
    course_description = '<p><p>Human rights have become the dominant language used to debate contentious social and political questions on a global scale. Activists appeal to human rights in defence of the oppressed. A complex set of global institutions has evolved, centred around human rights, while a flourishing field of academic inquiry is now devoted to debating human rights issues. </p> <p>Our Bachelor of Human Rights is a unique, interdisciplinary program of study that equips you with the knowledge and skills necessary to engage with real-world issues in human rights, and related areas such as social justice. You''ll examine these ideas from a variety of perspectives; legal, historical, political, practical, and philosophical. You''ll also gain invaluable analytical skills essential for success in the workplace.</p></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<!-- RichTextCourseCard.cshtml --> Admission requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 85</li> <li>demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a> - applicants presenting with IELTS Academic require an overall score of at least 6.5 and no band less than 6.0</li> <li> satisfy any prerequisites for your preferred majors (refer to individual major descriptions for prerequisite details)</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> <p>Assured Pathway information</p> <p> If you have a professional career in mind, take advantage of one of our <a href="https://www.uwa.edu.au/study/courses-and-careers/our-courses-explained#postgrad">Assured Pathways</a>. An Assured Pathway gives you an assured place in one of our postgraduate professional courses (such as Law, Engineering or Medicine) from the start of your studies with us. The pathways combine a range of undergraduate and postgraduate courses, providing you with a clearer direction to your career of choice.</p> <p>Admission entry to UWA </p> <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p> Admission requirements',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-human-rights',
    updated_at = NOW()
WHERE cricos_course_code = '111640M';
UPDATE courses SET
    course_description = '<p><p>Recent world events — including the pandemic, war in Ukraine, supply chain disruptions, and climate-related emergencies — underscore the need for people trained to dynamically respond to crises of a global scale. </p> <p>UWA’s Bachelor of International Relations is a professional and practice-oriented program that provides the crucial conceptual knowledge and real-world experience required to tackle our most pressing global challenges. Students develop a rigorous understanding of International Relations from a range of perspectives — political, legal, historical and sociological. </p> <p>In line with UWA’s expertise and Perth’s geography, students receive unique training focusing on the Indo-Pacific region. This comprehensive program includes the option of completing a language major as well as multiple opportunities to develop industry networks, including through in-country fieldwork.</p></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = '<!-- RichTextCourseCard.cshtml --> Admission requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 70</li> <li>demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a> - applicants presenting with IELTS Academic require an overall score of at least 6.5 and no band less than 6.0</li> <li> satisfy any prerequisites for your preferred majors (refer to individual major descriptions for prerequisite details)</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> <p>Assured Pathway information</p> <p> If you have a professional career in mind, take advantage of one of our <a href="https://www.uwa.edu.au/study/courses-and-careers/our-courses-explained#postgrad">Assured Pathways</a>. An Assured Pathway gives you an assured place in one of our postgraduate professional courses (such as Law, Engineering or Medicine) from the start of your studies with us. The pathways combine a range of undergraduate and postgraduate courses, providing you with a clearer direction to your career of choice.</p> <p>Admission entry to UWA </p> <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p> Admission requirements',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-international-relations',
    updated_at = NOW()
WHERE cricos_course_code = '115274G';
UPDATE courses SET
    course_description = '<p><p>The Bachelor of Modern Languages enables you to study two languages in depth. You''ll achieve a high competency in the four macro skills of reading, listening, speaking, and writing, while acquiring a range of transferable skills such as communication, teamwork, problem-solving and interpersonal skills. <br/> <br/> Choose from Chinese, French, German, Indonesian, Italian, Japanese, Korean, and Spanish. All languages are available to absolute beginners. Chinese, French, German, Indonesian, Italian and Japanese also have higher entry points depending on prior study or background knowledge. <br/> <br/> Combining the Bachelor of Modern Languages with degrees like Engineering, Science, Arts, or Business provides you with a competitive advantage in the job market, both domestically and internationally.</p></p>',
    course_duration_per_week = 156,
    offshore_tuition_fee = NULL,
    onshore_tuition_fee = NULL,
    enrolment_fee = NULL,
    materials_fee = NULL,
    entry_requirements = 'Admission requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 80</li> <li>demonstrate <a></a><a href="/study/how-to-apply/english-language-requirements">English language competence</a> - applicants presenting with IELTS Academic require an overall score of at least 7.5 and no band less than 7.0</li> <li> satisfy any prerequisites for your preferred majors (refer to individual major descriptions for prerequisite details)</li> </ul> <p>You can view the prerequisites and recommended subjects for your chosen course <a href="/study/courses-and-careers/prerequisites-and-recommended-subjects">here</a>.</p> <p>View our <a href="/study/how-to-apply/entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> <p>Assured Pathway information</p> <p> If you have a professional career in mind, take advantage of one of our <a href="https://www.uwa.edu.au/study/courses-and-careers/our-courses-explained#postgrad">Assured Pathways</a>. An Assured Pathway gives you an assured place in one of our postgraduate professional courses (such as Law, Engineering or Medicine) from the start of your studies with us. The pathways combine a range of undergraduate and postgraduate courses, providing you with a clearer direction to your career of choice.</p> <p>Admission entry to UWA </p> <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a></a><a href="/study/how-to-apply/admission-entry-pathways">admission entry pathways</a>.</p>',
    apply_form = 'https://www.uwa.edu.au/study/courses/bachelor-of-modern-languages',
    updated_at = NOW()
WHERE cricos_course_code = '114371C';
UPDATE courses SET
    course_description = '<p><p>Are you passionate about making a positive impact on society and the environment and creating a sustainable future? Consider a degree in social and environmental sustainability. </p> <p>Our program provides a unique blend of social sciences, humanities, environmental studies, and policy. You''ll study the latest research and best practices in sustainability, hear from community and industry leaders and gain hands on experience in tackling complex social and environmental challenges. Through this program you can take one of 10 interdisciplinary science minors to extend your knowledge in a field of interest to you.</p> <p>Join us in creating a more equitable and sustainable future for all.</p></p>',
