UPDATE courses SET
    course_description = '<p>The Bachelor of Social Work develops your skills and knowledge to bring about positive change and socially just outcomes in the wellbeing of individuals, organisations and communities. Equipping you with the skills to advocate for and improve the lives of individuals, families and communities. Built in collaboration with industry, UWA''s Bachelor of Social Work will equip you with the skills for a successful career.</p>',
