    materials_fee = NULL,
    entry_requirements = '<!-- RichTextCourseCard.cshtml --> Admissions Requirements <p><strong>To be considered for this course you need to:</strong></p> <ul> <li>achieve a minimum ATAR of 70</li> <li>demonstrate <a href="https://www.uwa.edu.au/study/How-to-apply/english-language-requirements">English language competence</a>. Note that applicants presenting with IELTS require a score of 7.0 with no individual band less than 7.0; applicants presenting with iBT require a score of 94 overall with 27 for writing, 23 for speaking, and 24 for reading and listening; applicants presenting with PTE require a score of 70 with nothing below 70.</li> </ul> <p>View our <a href="https://www.uwa.edu.au/study/How-to-apply/Entry-requirements">admission requirements</a> for specific information, depending on your education history.</p> <p><strong>Admission entry to UWA </strong></p> <p>We offer a number of other pathways for you to gain entry into our undergraduate degrees if you do not meet the standard admission requirements. Learn more about our <a href="https://www.uwa.edu.au/study/How-to-apply/Admission-entry-pathways">admission entry pathways</a>.</p> Admissions Requirements',
